// Deterministic shutdown simulation — no timers, no randomness.
// Broker holds messages; ack() deletes; if a message is never acked,
// the visibility timeout 'expires' and the broker redelivers it.
function makeBroker(msgs) {
  const inflight = new Map(); // id -> msg (delivered, awaiting ack)
  const queue = [...msgs];
  return {
    deliver() { const m = queue.shift(); if (m) inflight.set(m.id, m); return m; },
    ack(id) { inflight.delete(id); },
    // grace period ended: anything still inflight is redelivered
    expireVisibility() { for (const m of inflight.values()) queue.push(m); inflight.clear(); },
    pending() { return queue.length; }
  };
}

function runWorker(broker, mode, sigtermAtStep) {
  const m = broker.deliver();
  if (mode === 'ack-before') broker.ack(m.id); // WRONG order
  // ... long processing begins ...
  const step = 1; // we are mid-job when SIGTERM lands
  if (step <= sigtermAtStep) {
    // process is SIGKILLed mid-job: it never reaches the ack-after point
    return 'killed-mid-job';
  }
  if (mode === 'ack-after') broker.ack(m.id); // unreachable here
  return 'completed';
}

const before = makeBroker([{ id: 'job-A' }]);
runWorker(before, 'ack-before', 1);
before.expireVisibility();
const afterLost = before.pending(); // 0 -> nothing to redeliver

const after = makeBroker([{ id: 'job-B' }]);
runWorker(after, 'ack-after', 1);
after.expireVisibility();
const afterSafe = after.pending(); // 1 -> redelivered

if (afterSafe === 1 && afterLost === 0) {
  console.log('SAFE: ack-after redelivered, ack-before lost');
} else {
  console.log('UNEXPECTED: before=' + afterLost + ' after=' + afterSafe);
}
